        <div class="sl-learn-tool-fields" data-tool="normal"><div class="sl-learn-input-grid"><label>میانگین μ<input name="mu" inputmode="decimal" value="<?= $v('mu', '0') ?>"></label><label>انحراف معیار σ<input name="sigma" inputmode="decimal" value="<?= $v('sigma', '1') ?>"></label><label>کران اول<input name="x1" inputmode="decimal" value="<?= $v('x1', '0') ?>"></label><label>کران دوم (اختیاری؛ خالی یعنی دنباله راست)<input name="x2" inputmode="decimal" value="<?= $v('x2') ?>"></label></div></div>
