    <?php if ($result): ?><section class="sl-learn-panel sl-learn-tool-result"><h2><?= $h($result['title'] ?? 'نتیجه محاسبه') ?></h2><?php if (!empty($result['error'])): ?><p class="sl-learn-error"><?= $h($result['error']) ?></p><?php else: ?><dl><?php foreach ($result['metrics'] ?? [] as [$label, $value]): ?><div><dt><?= $h($label) ?></dt><dd><?= $h($value) ?></dd></div><?php endforeach; ?></dl><?php if (!empty($result['note'])): ?><p class="sl-learn-result-note"><?= $h($result['note']) ?></p><?php endif; ?><?php if (!empty($result['interpretation'])): ?><p><?= nl2br($h($result['interpretation'])) ?></p><?php endif; ?><?php foreach ($result['warnings'] ?? [] as $warning): ?><p class="sl-learn-warning"><?= $h($warning) ?></p><?php endforeach; ?><?php endif; ?></section><?php endif; ?>
