</main>
<script>
(() => { const select = document.getElementById('sl-tool'); const fields = document.querySelectorAll('.sl-learn-tool-fields'); const update = () => fields.forEach((field) => { const active = field.dataset.tool === select.value; field.hidden = !active; field.querySelectorAll('input,textarea,select').forEach((input) => { input.disabled = !active; }); }); select.addEventListener('change', update); update(); })();
</script>
